using NUnit.Framework; using AuraFarming.Domain; using AuraFarming.Presentation; namespace AuraFarming.Tests { public class WinnerAnimationDirectorTests { [Test] public void MapsCanonicalCardIdsToTriggers(){string[] e={"PlayCaptain","PlaySixSeven","PlayAuraWalk","PlayMewing","PlayStinkyDance","PlayAnimePose","PlaySigmaLook","PlayAdjustGlasses","PlaySilence","PlaySnap"};for(int i=0;i<e.Length;i++)Assert.AreEqual(e[i],WinnerAnimationDirector.GetTrigger(new SignalCardId(i+1)));} [Test] public void UnknownCardHasSafeFallback(){Assert.IsNull(WinnerAnimationDirector.GetTrigger(new SignalCardId(11)));} } }